def validate_transaction(node, cache=None):
    if cache is None:
        cache = {}

    if node is None:
        return 0

    if node in cache:
        return cache[node]

    left_val = validate_transaction(node.left, cache) if node.left else 0
    right_val = validate_transaction(node.right, cache) if node.right else 0

    result = 1 + left_val + right_val

    cache[node] = result
    return result
